7	import { Box, Text } from 'ink';
8	import type React from 'react';
9	import { useEffect, useState, useCallback } from 'react';
10	import { theme } from '../semantic-colors.js';
11	import type { RadioSelectItem } from './shared/RadioButtonSelect.js';
12	import { RadioButtonSelect } from './shared/RadioButtonSelect.js';
13	import { useKeypress } from '../hooks/useKeypress.js';
14	import * as process from 'node:process';
15	import * as path from 'node:path';
16	import { relaunchApp } from '../../utils/processUtils.js';
17	import { runExitCleanup } from '../../utils/cleanup.js';
18	import { ExitCodes } from '@google/gemini-cli-core';
19	
20	export enum FolderTrustChoice {
21	  TRUST_FOLDER = 'trust_folder',
22	  TRUST_PARENT = 'trust_parent',
23	  DO_NOT_TRUST = 'do_not_trust',
24	}
25	
26	interface FolderTrustDialogProps {
27	  onSelect: (choice: FolderTrustChoice) => void;
28	  isRestarting?: boolean;
29	}
30	
31	export const FolderTrustDialog: React.FC<FolderTrustDialogProps> = ({
32	  onSelect,
33	  isRestarting,
34	}) => {
35	  const [exiting, setExiting] = useState(false);
36	
37	  useEffect(() => {
38	    let timer: ReturnType<typeof setTimeout>;
39	    if (isRestarting) {
40	      timer = setTimeout(async () => {
41	        await relaunchApp();
42	      }, 250);
43	    }
44	    return () => {
45	      if (timer) clearTimeout(timer);
46	    };
47	  }, [isRestarting]);
48	
49	  const handleExit = useCallback(() => {
50	    setExiting(true);
51	    // Give time for the UI to render the exiting message
52	    setTimeout(async () => {
53	      await runExitCleanup();
54	      process.exit(ExitCodes.FATAL_CANCELLATION_ERROR);
55	    }, 100);
56	  }, []);
57	
58	  useKeypress(
59	    (key) => {
60	      if (key.name === 'escape') {
61	        handleExit();
62	        return true;
63	      }
64	      return false;
65	    },
66	    { isActive: !isRestarting },
67	  );
68	
69	  const dirName = path.basename(process.cwd());
70	  const parentFolder = path.basename(path.dirname(process.cwd()));
71	
72	  const options: Array<RadioSelectItem<FolderTrustChoice>> = [
73	    {
74	      label: `Trust folder (${dirName})`,
75	      value: FolderTrustChoice.TRUST_FOLDER,
76	      key: `Trust folder (${dirName})`,
77	    },
78	    {
79	      label: `Trust parent folder (${parentFolder})`,
80	      value: FolderTrustChoice.TRUST_PARENT,
81	      key: `Trust parent folder (${parentFolder})`,
82	    },
83	    {
84	      label: "Don't trust",
85	      value: FolderTrustChoice.DO_NOT_TRUST,
86	      key: "Don't trust",
87	    },
88	  ];
89	
90	  return (
91	    <Box flexDirection="column" width="100%">
92	      <Box
93	        flexDirection="column"
94	        borderStyle="round"
95	        borderColor={theme.status.warning}
96	        padding={1}
97	        marginLeft={1}
98	        marginRight={1}
99	      >
100	        <Box flexDirection="column" marginBottom={1}>
101	          <Text bold color={theme.text.primary}>
102	            Do you trust this folder?
103	          </Text>
104	          <Text color={theme.text.primary}>
105	            Trusting a folder allows Gemini to execute commands it suggests.
106	            This is a security feature to prevent accidental execution in
107	            untrusted directories.
108	          </Text>
109	        </Box>
110	
111	        <RadioButtonSelect
112	          items={options}
113	          onSelect={onSelect}
114	          isFocused={!isRestarting}
115	        />
116	      </Box>
117	      {isRestarting && (
118	        <Box marginLeft={1} marginTop={1}>
119	          <Text color={theme.status.warning}>
120	            Gemini CLI is restarting to apply the trust changes...
121	          </Text>
122	        </Box>
123	      )}
124	      {exiting && (
125	        <Box marginLeft={1} marginTop={1}>
126	          <Text color={theme.status.warning}>
127	            A folder trust level must be selected to continue. Exiting since
128	            escape was pressed.
129	          </Text>
130	        </Box>
131	      )}
132	    </Box>
133	  );
134	};
