9	import { GitIgnoreParser } from '../utils/gitIgnoreParser.js';
10	import { IgnoreFileParser } from '../utils/ignoreFileParser.js';
11	import { isGitRepository } from '../utils/gitUtils.js';
12	import { GEMINI_IGNORE_FILE_NAME } from '../config/constants.js';
13	import fs from 'node:fs';
14	import * as path from 'node:path';
15	
16	export interface FilterFilesOptions {
17	  respectGitIgnore?: boolean;
18	  respectGeminiIgnore?: boolean;
19	  customIgnoreFilePaths?: string[];
20	}
21	
22	export interface FilterReport {
23	  filteredPaths: string[];
24	  ignoredCount: number;
25	}
26	
27	export class FileDiscoveryService {
28	  private gitIgnoreFilter: GitIgnoreFilter | null = null;
29	  private geminiIgnoreFilter: IgnoreFileFilter | null = null;
30	  private customIgnoreFilter: IgnoreFileFilter | null = null;
31	  private combinedIgnoreFilter: GitIgnoreFilter | IgnoreFileFilter | null =
32	    null;
33	  private defaultFilterFileOptions: FilterFilesOptions = {
34	    respectGitIgnore: true,
35	    respectGeminiIgnore: true,
36	    customIgnoreFilePaths: [],
37	  };
38	  private projectRoot: string;
39	
40	  constructor(projectRoot: string, options?: FilterFilesOptions) {
41	    this.projectRoot = path.resolve(projectRoot);
42	    this.applyFilterFilesOptions(options);
43	    if (isGitRepository(this.projectRoot)) {
44	      this.gitIgnoreFilter = new GitIgnoreParser(this.projectRoot);
45	    }
46	    this.geminiIgnoreFilter = new IgnoreFileParser(
47	      this.projectRoot,
48	      GEMINI_IGNORE_FILE_NAME,
49	    );
50	    if (this.defaultFilterFileOptions.customIgnoreFilePaths?.length) {
51	      this.customIgnoreFilter = new IgnoreFileParser(
52	        this.projectRoot,
53	        this.defaultFilterFileOptions.customIgnoreFilePaths,
54	      );
55	    }
56	
57	    if (this.gitIgnoreFilter) {
58	      const geminiPatterns = this.geminiIgnoreFilter.getPatterns();
59	      const customPatterns = this.customIgnoreFilter
60	        ? this.customIgnoreFilter.getPatterns()
61	        : [];
62	      // Create combined parser: .gitignore + .geminiignore + custom ignore
63	      this.combinedIgnoreFilter = new GitIgnoreParser(
64	        this.projectRoot,
65	        // customPatterns should go the last to ensure overwriting of geminiPatterns
66	        [...geminiPatterns, ...customPatterns],
67	      );
68	    } else {
69	      // Create combined parser when not git repo
70	      const geminiPatterns = this.geminiIgnoreFilter.getPatterns();
71	      const customPatterns = this.customIgnoreFilter
72	        ? this.customIgnoreFilter.getPatterns()
73	        : [];
74	      this.combinedIgnoreFilter = new IgnoreFileParser(
75	        this.projectRoot,
76	        [...geminiPatterns, ...customPatterns],
77	        true,
78	      );
79	    }
80	  }
81	
82	  private applyFilterFilesOptions(options?: FilterFilesOptions): void {
83	    if (!options) return;
84	
85	    if (options.respectGitIgnore !== undefined) {
86	      this.defaultFilterFileOptions.respectGitIgnore = options.respectGitIgnore;
87	    }
88	    if (options.respectGeminiIgnore !== undefined) {
89	      this.defaultFilterFileOptions.respectGeminiIgnore =
90	        options.respectGeminiIgnore;
91	    }
92	    if (options.customIgnoreFilePaths) {
93	      this.defaultFilterFileOptions.customIgnoreFilePaths =
94	        options.customIgnoreFilePaths;
95	    }
96	  }
97	
98	  /**
99	   * Filters a list of file paths based on ignore rules
100	   */
101	  filterFiles(filePaths: string[], options: FilterFilesOptions = {}): string[] {
102	    const {
103	      respectGitIgnore = this.defaultFilterFileOptions.respectGitIgnore,
104	      respectGeminiIgnore = this.defaultFilterFileOptions.respectGeminiIgnore,
105	    } = options;
106	    return filePaths.filter((filePath) => {
107	      if (
108	        respectGitIgnore &&
109	        respectGeminiIgnore &&
110	        this.combinedIgnoreFilter
111	      ) {
112	        return !this.combinedIgnoreFilter.isIgnored(filePath);
113	      }
114	
115	      // Always respect custom ignore filter if provided
116	      if (this.customIgnoreFilter?.isIgnored(filePath)) {
117	        return false;
118	      }
119	
120	      if (respectGitIgnore && this.gitIgnoreFilter?.isIgnored(filePath)) {
121	        return false;
122	      }
123	      if (respectGeminiIgnore && this.geminiIgnoreFilter?.isIgnored(filePath)) {
124	        return false;
125	      }
126	      return true;
127	    });
128	  }
129	
130	  /**
131	   * Filters a list of file paths based on git ignore rules and returns a report
132	   * with counts of ignored files.
133	   */
134	  filterFilesWithReport(
135	    filePaths: string[],
136	    opts: FilterFilesOptions = {
137	      respectGitIgnore: true,
138	      respectGeminiIgnore: true,
139	    },
140	  ): FilterReport {
141	    const filteredPaths = this.filterFiles(filePaths, opts);
142	    const ignoredCount = filePaths.length - filteredPaths.length;
143	
144	    return {
145	      filteredPaths,
146	      ignoredCount,
147	    };
148	  }
149	
150	  /**
151	   * Unified method to check if a file should be ignored based on filtering options
152	   */
153	  shouldIgnoreFile(
154	    filePath: string,
155	    options: FilterFilesOptions = {},
156	  ): boolean {
157	    return this.filterFiles([filePath], options).length === 0;
158	  }
159	
160	  /**
161	   * Returns the list of ignore files being used (e.g. .geminiignore) excluding .gitignore.
162	   */
163	  getIgnoreFilePaths(): string[] {
164	    const paths: string[] = [];
165	    if (
166	      this.geminiIgnoreFilter &&
167	      this.defaultFilterFileOptions.respectGeminiIgnore
168	    ) {
169	      paths.push(...this.geminiIgnoreFilter.getIgnoreFilePaths());
170	    }
171	    if (this.customIgnoreFilter) {
172	      paths.push(...this.customIgnoreFilter.getIgnoreFilePaths());
173	    }
174	    return paths;
175	  }
176	
177	  /**
178	   * Returns all ignore files including .gitignore if applicable.
179	   */
180	  getAllIgnoreFilePaths(): string[] {
181	    const paths: string[] = [];
182	    if (
183	      this.gitIgnoreFilter &&
184	      this.defaultFilterFileOptions.respectGitIgnore
185	    ) {
186	      const gitIgnorePath = path.join(this.projectRoot, '.gitignore');
187	      if (fs.existsSync(gitIgnorePath)) {
188	        paths.push(gitIgnorePath);
189	      }
190	    }
191	    return paths.concat(this.getIgnoreFilePaths());
192	  }
193	}
