import { promises as fs } from 'node:fs';
import * as path from 'node:path';
import { GEMINI_DIR } from '../utils/paths.js';

/**
 * Summary of the configuration discovered inside a workspace's `.gemini`
 * directory. Every field is always present so consumers can render the results
 * without additional null checks.
 */
export interface FolderDiscoveryResults {
  /** Custom slash command names discovered from `commands/*.toml`. */
  commands: string[];
  /** MCP server names discovered from `settings.json`. */
  mcps: string[];
  /** Hook command strings discovered from `settings.json`. */
  hooks: string[];
  /** Skill names discovered from `skills/<name>/SKILL.md`. */
  skills: string[];
  /** Top-level `settings.json` keys (excluding `mcpServers` and `hooks`). */
  settings: string[];
  /** Human readable warnings about potentially risky configuration. */
  securityWarnings: string[];
  /** Errors encountered while scanning the configuration directory. */
  discoveryErrors: string[];
}

/**
 * Keys in `settings.json` that are surfaced through their own dedicated
 * discovery buckets and therefore excluded from the generic `settings` list.
 */
const SETTINGS_EXCLUDED_KEYS = new Set(['mcpServers', 'hooks']);

function createEmptyResults(): FolderDiscoveryResults {
  return {
    commands: [],
    mcps: [],
    hooks: [],
    skills: [],
    settings: [],
    securityWarnings: [],
    discoveryErrors: [],
  };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' && value !== null && !Array.isArray(value)
  );
}

async function pathExists(target: string): Promise<boolean> {
  try {
    await fs.access(target);
    return true;
  } catch {
    return false;
  }
}

/**
 * Scans a workspace's `.gemini` directory and summarizes the project-specific
 * configuration a user would enable by trusting the folder. This lets the trust
 * dialog surface exactly what a folder can do before the user grants trust.
 */
export class FolderTrustDiscoveryService {
  /**
   * Scans the given workspace directory for project configuration.
   *
   * If the `.gemini` directory does not exist, an empty result (with no errors)
   * is returned. Individual discovery steps fail independently: an error in one
   * step is recorded in `discoveryErrors` without aborting the others.
   */
  static async discover(
    workspaceDir: string,
  ): Promise<FolderDiscoveryResults> {
    const results = createEmptyResults();
    const geminiDir = path.join(workspaceDir, GEMINI_DIR);

    if (!(await pathExists(geminiDir))) {
      return results;
    }

    await FolderTrustDiscoveryService.discoverCommands(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSkills(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSettings(geminiDir, results);

    FolderTrustDiscoveryService.generateSecurityWarnings(results);

    return results;
  }

  private static async discoverCommands(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const commandsDir = path.join(geminiDir, 'commands');
    if (!(await pathExists(commandsDir))) {
      return;
    }

    try {
      const tomlFiles = await FolderTrustDiscoveryService.findFiles(
        commandsDir,
        '.toml',
      );
      const names = tomlFiles.map((file) => {
        const relative = path.relative(commandsDir, file);
        const withoutExt = relative.slice(0, relative.length - '.toml'.length);
        return withoutExt.split(path.sep).join(':');
      });
      names.sort((a, b) => a.localeCompare(b));
      results.commands.push(...names);
    } catch (error) {
      results.discoveryErrors.push(
        `Failed to discover commands: ${getErrorMessage(error)}`,
      );
    }
  }

  private static async discoverSkills(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const skillsDir = path.join(geminiDir, 'skills');
    if (!(await pathExists(skillsDir))) {
      return;
    }

    try {
      const entries = await fs.readdir(skillsDir, { withFileTypes: true });
      const skills: string[] = [];
      for (const entry of entries) {
        if (!entry.isDirectory()) {
          continue;
        }
        const skillFile = path.join(skillsDir, entry.name, 'SKILL.md');
        if (await pathExists(skillFile)) {
          skills.push(entry.name);
        }
      }
      skills.sort((a, b) => a.localeCompare(b));
      results.skills.push(...skills);
    } catch (error) {
      results.discoveryErrors.push(
        `Failed to discover skills: ${getErrorMessage(error)}`,
      );
    }
  }

  private static async discoverSettings(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const settingsFile = path.join(geminiDir, 'settings.json');
    if (!(await pathExists(settingsFile))) {
      return;
    }

    let parsed: unknown;
    try {
      const content = await fs.readFile(settingsFile, 'utf-8');
      parsed = JSON.parse(content);
    } catch (error) {
      results.discoveryErrors.push(
        `Failed to discover settings: ${getErrorMessage(error)}`,
      );
      return;
    }

    // Non-object roots (arrays, strings, numbers, null) carry no discoverable
    // settings. This is not an error condition.
    if (!isPlainObject(parsed)) {
      return;
    }

    // MCP servers.
    const mcpServers = parsed['mcpServers'];
    if (isPlainObject(mcpServers)) {
      results.mcps.push(...Object.keys(mcpServers));
    }

    // Hooks.
    results.hooks.push(...extractHookCommands(parsed['hooks']));

    // Remaining top-level settings keys.
    for (const key of Object.keys(parsed)) {
      if (!SETTINGS_EXCLUDED_KEYS.has(key)) {
        results.settings.push(key);
      }
    }
  }

  private static generateSecurityWarnings(
    results: FolderDiscoveryResults,
  ): void {
    if (results.mcps.length > 0) {
      results.securityWarnings.push(
        'This folder configures MCP servers which can run external programs and access external resources.',
      );
    }
    if (results.hooks.length > 0) {
      results.securityWarnings.push(
        'This folder configures hooks which can execute shell commands automatically.',
      );
    }
    if (results.commands.length > 0) {
      results.securityWarnings.push(
        'This folder defines custom commands which may execute shell commands.',
      );
    }
  }

  /**
   * Recursively collects files with the given extension under `dir`.
   */
  private static async findFiles(
    dir: string,
    extension: string,
  ): Promise<string[]> {
    const found: string[] = [];
    const entries = await fs.readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        found.push(
          ...(await FolderTrustDiscoveryService.findFiles(fullPath, extension)),
        );
      } else if (entry.isFile() && entry.name.endsWith(extension)) {
        found.push(fullPath);
      }
    }
    return found;
  }
}

