import { Box, Text } from 'ink';
import type React from 'react';
import { useEffect, useState, useCallback, useMemo } from 'react';
import stripAnsi from 'strip-ansi';
import { theme } from '../semantic-colors.js';
import type { RadioSelectItem } from './shared/RadioButtonSelect.js';
import { RadioButtonSelect } from './shared/RadioButtonSelect.js';
import { Scrollable } from './shared/Scrollable.js';
import { useKeypress } from '../hooks/useKeypress.js';
import { useUIState } from '../contexts/UIStateContext.js';
import { useAlternateBuffer } from '../hooks/useAlternateBuffer.js';
import * as process from 'node:process';
import * as path from 'node:path';
import { relaunchApp } from '../../utils/processUtils.js';
import { runExitCleanup } from '../../utils/cleanup.js';
import { ExitCodes } from '@google/gemini-cli-core';
import type { FolderDiscoveryResults } from '@google/gemini-cli-core';

export enum FolderTrustChoice {
  TRUST_FOLDER = 'trust_folder',
  TRUST_PARENT = 'trust_parent',
  DO_NOT_TRUST = 'do_not_trust',
}

interface FolderTrustDialogProps {
  onSelect: (choice: FolderTrustChoice) => void;
  isRestarting?: boolean;
  discoveryResults?: FolderDiscoveryResults | null;
}

interface DiscoveryGroup {
  label: string;
  items: string[];
}

// Rough estimate of how many terminal rows are consumed by the dialog chrome
// (border, title, description, options and the surrounding margins). The
// remaining rows are what we can dedicate to the discovery summary before we
// need to truncate or scroll.
const DIALOG_CHROME_ROWS = 14;
const MIN_DISCOVERY_ROWS = 4;

const sanitize = (value: string): string => stripAnsi(value);

export const FolderTrustDialog: React.FC<FolderTrustDialogProps> = ({
  onSelect,
  isRestarting,
  discoveryResults,
}) => {
  const [exiting, setExiting] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const uiState = useUIState();
  const isAlternateBuffer = useAlternateBuffer();

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isRestarting) {
      timer = setTimeout(async () => {
        await relaunchApp();
      }, 250);
    }
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [isRestarting]);

  const handleExit = useCallback(() => {
    setExiting(true);
    // Give time for the UI to render the exiting message
    setTimeout(async () => {
      await runExitCleanup();
      process.exit(ExitCodes.FATAL_CANCELLATION_ERROR);
    }, 100);
  }, []);

  useKeypress(
    (key) => {
      if (key.name === 'escape') {
        handleExit();
        return true;
      }
      // Allow expanding the (truncated) discovery summary with ctrl+s.
      if (key.ctrl && key.name === 's') {
        setExpanded((prev) => !prev);
        return true;
      }
      return false;
    },
    { isActive: !isRestarting },
  );

  const dirName = path.basename(process.cwd());
  const parentFolder = path.basename(path.dirname(process.cwd()));

  const options: Array<RadioSelectItem<FolderTrustChoice>> = [
    {
      label: `Trust folder (${dirName})`,
      value: FolderTrustChoice.TRUST_FOLDER,
      key: `Trust folder (${dirName})`,
    },
    {
      label: `Trust parent folder (${parentFolder})`,
      value: FolderTrustChoice.TRUST_PARENT,
      key: `Trust parent folder (${parentFolder})`,
    },
    {
      label: "Don't trust",
      value: FolderTrustChoice.DO_NOT_TRUST,
      key: "Don't trust",
    },
  ];

  const groups = useMemo<DiscoveryGroup[]>(() => {
    if (!discoveryResults) {
      return [];
    }
    const candidates: DiscoveryGroup[] = [
      { label: 'Commands', items: discoveryResults.commands },
      { label: 'MCP Servers', items: discoveryResults.mcps },
      { label: 'Hooks', items: discoveryResults.hooks },
      { label: 'Skills', items: discoveryResults.skills },
      { label: 'Settings', items: discoveryResults.settings },
    ];
    return candidates.filter((group) => group.items.length > 0);
  }, [discoveryResults]);

  const hasDiscovery =
    !!discoveryResults &&
    (groups.length > 0 ||
      discoveryResults.securityWarnings.length > 0 ||
      discoveryResults.discoveryErrors.length > 0);

  // Build the discovery summary as a flat list of renderable lines so we can
  // truncate or scroll it based on the available terminal height.
  const discoveryLines: React.ReactNode[] = [];
  if (hasDiscovery && discoveryResults) {
    if (groups.length > 0) {
      discoveryLines.push(
        <Text key="contains-header" bold color={theme.text.primary}>
          This folder contains:
        </Text>,
      );
      for (const group of groups) {
        const names = group.items.map((item) => sanitize(item)).join(', ');
        discoveryLines.push(
          <Text key={`group-${group.label}`} color={theme.text.primary}>
            {'  '}
            <Text color={theme.text.accent}>
              {group.label} ({group.items.length})
            </Text>
            {': '}
            <Text color={theme.text.secondary}>{names}</Text>
          </Text>,
        );
      }
    }

    if (discoveryResults.securityWarnings.length > 0) {
      discoveryLines.push(
        <Text key="warnings-header" bold color={theme.status.warning}>
          Security Warnings:
        </Text>,
      );
      for (const [index, warning] of discoveryResults.securityWarnings.entries()) {
        discoveryLines.push(
          <Text key={`warning-${index}`} color={theme.status.warning}>
            {'  '}⚠ {sanitize(warning)}
          </Text>,
        );
      }
    }

    if (discoveryResults.discoveryErrors.length > 0) {
      discoveryLines.push(
        <Text key="errors-header" bold color={theme.status.error}>
          Discovery Errors:
        </Text>,
      );
      for (const [index, error] of discoveryResults.discoveryErrors.entries()) {
        discoveryLines.push(
          <Text key={`error-${index}`} color={theme.status.error}>
            {'  '}✗ {sanitize(error)}
          </Text>,
        );
      }
    }
  }

  const availableDiscoveryRows = Math.max(
    MIN_DISCOVERY_ROWS,
    (uiState.terminalHeight ?? 0) - DIALOG_CHROME_ROWS,
  );

  const renderDiscovery = () => {
    if (discoveryLines.length === 0) {
      return null;
    }

    // In full-screen mode (alternate buffer) we can rely on a scroll region
    // instead of hiding content.
    if (isAlternateBuffer) {
      return (
        <Box flexDirection="column" marginBottom={1}>
          <Scrollable hasFocus={false} maxHeight={availableDiscoveryRows}>
            {discoveryLines}
          </Scrollable>
        </Box>
      );
    }

    // Otherwise, when the summary is taller than the space we have, truncate it
    // and let the user expand it with ctrl+s.
    const needsTruncation =
      !expanded && discoveryLines.length > availableDiscoveryRows;
    const visibleLines = needsTruncation
      ? discoveryLines.slice(0, Math.max(1, availableDiscoveryRows - 1))
      : discoveryLines;

    return (
      <Box flexDirection="column" marginBottom={1}>
        {visibleLines}
        {needsTruncation && (
          <Text color={theme.text.secondary}>
            ...{discoveryLines.length - visibleLines.length} more line
            {discoveryLines.length - visibleLines.length === 1 ? '' : 's'}{' '}
            hidden. Press ctrl+s to expand.
          </Text>

