import { renderWithProviders } from '../../test-utils/render.js';
import { describe, it, expect, vi } from 'vitest';
import { FolderTrustDialog } from './FolderTrustDialog.js';
import type { FolderDiscoveryResults } from '@google/gemini-cli-core';

describe('scratch discovery', () => {
  it('renders discovery contents and strips ansi', async () => {
    const results: FolderDiscoveryResults = {
      commands: ['deploy', 'git:commit'],
      mcps: ['[31mredname[0m'],
      hooks: ['echo hi'],
      skills: ['mySkill'],
      settings: ['theme', 'model'],
      securityWarnings: ['dangerous thing'],
      discoveryErrors: ['some error'],
    };
    const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
      <FolderTrustDialog onSelect={vi.fn()} discoveryResults={results} />,
      { useAlternateBuffer: false },
    );
    await waitUntilReady();
    const frame = lastFrame();
    expect(frame).toContain('This folder contains:');
    expect(frame).toContain('Commands (2)');
    expect(frame).toContain('deploy');
    expect(frame).toContain('MCP Servers (1)');
    expect(frame).toContain('redname');
    expect(frame).not.toContain('[31m');
    expect(frame).toContain('Security Warnings:');
    expect(frame).toContain('dangerous thing');
    expect(frame).toContain('Discovery Errors:');
    expect(frame).toContain('some error');
    unmount();
  });
});
